  teleTitle: "ปรึกษาเภสัชกร",
  teleIntro: "คุยกับเภสัชกรทางวิดีโอเมื่อต้องตัดสินใจเรื่องผลิตภัณฑ์ ยา หรือบริการ เลือกคุยตอนนี้ถ้ามีเภสัชกรว่าง หรือจองเวลาล่วงหน้า",
  teleDisclaimerDraft: "เภสัชกรให้คำปรึกษาเบื้องต้นเกี่ยวกับการใช้ยาและผลิตภัณฑ์สุขภาพ ไม่ใช่การวินิจฉัยโรคหรือการรักษา และไม่แทนที่แพทย์ หากมีอาการฉุกเฉิน เช่น เจ็บหน้าอก หายใจไม่ออก ให้โทร 1669 ทันที ห้ามรอคิวปรึกษา",
  teleConsentDraft: "ข้อความยินยอม (ฉบับร่าง รอตรวจโดยเภสัชกรผู้รับอนุญาตและที่ปรึกษากฎหมายก่อนเปิดใช้จริง): ข้าพเจ้ายินยอมให้รู้สุขและเภสัชกรเข้าถึงข้อมูลส่วนบุคคลและข้อมูลสุขภาพที่ข้าพเจ้าเลือกแชร์ เพื่อให้คำปรึกษาและจัดทำบันทึกการให้บริการเภสัชกรรม ข้อมูลที่แชร์เป็นสำเนา ณ เวลาที่ส่งคำขอ ทุกครั้งที่มีผู้เปิดดูจะถูกบันทึกไว้และข้าพเจ้าตรวจดูได้ ข้าพเจ้าถอนความยินยอมในการแชร์ข้อมูลครั้งต่อไปได้ แต่บันทึกการให้บริการที่จัดทำแล้วอาจต้องเก็บไว้ตามกฎหมาย",
  teleOffTitle: "บริการยังไม่เปิด",
